16	#ifdef _WIN32
17	  if (mkdir(path) == 0 || errno == EEXIST)
18	#else
19	  if (mkdir(path, 0777) == 0 || errno == EEXIST)
20	#endif
21	    {
22	      if (stat(path, &st) == 0 && S_ISDIR(st.st_mode))
