31	int storage_ensure_dir(const char *path)
32	{
33	  char temp[160];
34	  size_t len = 0;
35	
36	  if (path == NULL || path[0] == '\0')
37	    {
38	      return -1;
39	    }
40	
41	  snprintf(temp, sizeof(temp), "%s", path);
42	  len = strlen(temp);
43	  if (len == 0)
44	    {
45	      return -1;
46	    }
47	
48	  for (size_t i = 1; i < len; i++)
49	    {
50	      if (temp[i] == '/')
51	        {
52	          temp[i] = '\0';
53	          if (strlen(temp) > 0 && mkdir_if_missing(temp) < 0)
54	            {
55	              return -1;
56	            }
57	
58	          temp[i] = '/';
59	        }
60	    }
61	
62	  return mkdir_if_missing(temp);
63	}
