65	int storage_read_all(const char *path, char **out_buffer)
66	{
67	  FILE *fp = NULL;
68	  long size = 0;
69	  char *buffer = NULL;
70	  size_t read_len = 0;
71	
72	  if (path == NULL || out_buffer == NULL)
73	    {
74	      return -1;
75	    }
76	
77	  *out_buffer = NULL;
78	  fp = fopen(path, "rb");
79	  if (fp == NULL)
80	    {
81	      return -1;
82	    }
83	
84	  if (fseek(fp, 0, SEEK_END) != 0)
85	    {
86	      fclose(fp);
87	      return -1;
88	    }
89	
90	  size = ftell(fp);
91	  if (size < 0)
92	    {
93	      fclose(fp);
94	      return -1;
95	    }
96	
97	  rewind(fp);
98	  buffer = (char *)calloc((size_t)size + 1, 1);
99	  if (buffer == NULL)
100	    {
101	      fclose(fp);
102	      return -1;
103	    }
104	
105	  read_len = fread(buffer, 1, (size_t)size, fp);
106	  fclose(fp);
107	  if (read_len != (size_t)size)
108	    {
109	      free(buffer);
110	      return -1;
111	    }
112	
113	  *out_buffer = buffer;
114	  return 0;
115	}
