117	int storage_write_all(const char *path, const char *data, size_t len)
118	{
119	  FILE *fp = NULL;
120	  const char *last_slash = NULL;
121	  char dir[160];
122	  size_t written = 0;
123	
124	  if (path == NULL || data == NULL)
125	    {
126	      return -1;
127	    }
128	
129	  last_slash = strrchr(path, '/');
130	  if (last_slash != NULL && last_slash != path)
131	    {
132	      size_t dir_len = (size_t)(last_slash - path);
133	      if (dir_len >= sizeof(dir))
134	        {
135	          return -1;
136	        }
137	
138	      memcpy(dir, path, dir_len);
139	      dir[dir_len] = '\0';
140	      if (storage_ensure_dir(dir) < 0)
141	        {
142	          return -1;
143	        }
144	    }
145	
146	  fp = fopen(path, "wb");
147	  if (fp == NULL)
148	    {
149	      return -1;
150	    }
151	
152	  written = fwrite(data, 1, len, fp);
153	  fclose(fp);
154	  return written == len ? 0 : -1;
155	}
