127	        lv_label_set_text(s_face_label, face_text);
128	    }
129	    if (source_text != NULL) {
130	        snprintf(buf, sizeof(buf), "%s\n%s", state_text, source_text);
131	    } else {
132	        snprintf(buf, sizeof(buf), "%s\nImage source: %s", state_text, s_asset_path);
133	    }
