61	    tasks[task_index].status = TASK_STATUS_REWARD_CLAIMED;
62	    s_pet.exp += tasks[task_index].exp_reward;
63	    if (s_pet.exp >= s_pet.exp_to_next) {
64	        s_pet.level += 1;
