#!/bin/bash
set -u
APP=/root/openvela/apps/examples/velapet
CJ=/root/openvela/apps/netutils/cjson/cJSON
TESTDIR=/tmp/velapet_store_test
SRC=/tmp/velapet_storage_test.c

cat > "$SRC" <<'EOF'
#include "storage.h"

#include <assert.h>
#include <stdio.h>
#include <string.h>

static int exists(const char *path)
{
  FILE *fp = fopen(path, "rb");
  if (fp == NULL) return 0;
  fclose(fp);
  return 1;
}

int main(void)
{
  char tmp[256];
  struct stat_unused { int x; };
  (void)sizeof(struct stat_unused);

  PetProfile *pet = pet_create_default();
  TaskLog *log = task_log_create_default();
  assert(pet != NULL && log != NULL);

  pet->level = 3;
  pet->exp = 42;
  assert(vela_pet_save_state(pet, log) == 0);

  assert(exists(VELAPET_PET_PROFILE_PATH));
  assert(exists(VELAPET_TASK_LOG_PATH));

  /* No temporary file must be left behind after a successful save. */
  snprintf(tmp, sizeof(tmp), "%s.tmp", VELAPET_PET_PROFILE_PATH);
  assert(!exists(tmp));

  PetProfile *pet2 = NULL;
  TaskLog *log2 = NULL;
  assert(vela_pet_restore_state(&pet2, &log2) == 0);
  assert(pet2 != NULL && log2 != NULL);
  assert(pet2->level == 3);
  assert(pet2->exp == 42);

  /* A second save over an existing file must also succeed. */
  pet2->exp = 7;
  assert(vela_pet_save_state(pet2, log2) == 0);
  snprintf(tmp, sizeof(tmp), "%s.tmp", VELAPET_PET_PROFILE_PATH);
  assert(!exists(tmp));

  printf("storage atomic round-trip ok: level=%d exp=%d\n",
         pet2->level, pet2->exp);

  pet_free(pet);
  task_log_free(log);
  pet_free(pet2);
  task_log_free(log2);
  return 0;
}
EOF

cd "$APP" || exit 1
rm -rf "$TESTDIR"

echo "=== compile ==="
gcc -Wall -Wextra -g \
  -Isrc -I"$CJ" \
  -DCONFIG_VELAPET_DATA_PATH='"/tmp/velapet_store_test"' \
  "$SRC" \
  src/pet.c src/task.c src/reward.c src/json_utils.c src/storage.c \
  "$CJ/cJSON.c" \
  -lpthread -lm \
  -o /tmp/velapet_storage_test 2>&1
rc=$?
echo "compile exit: $rc"
if [ $rc -ne 0 ]; then exit $rc; fi

echo "=== run ==="
/tmp/velapet_storage_test
rc=$?
echo "run exit: $rc"
echo "=== resulting files ==="
ls -la "$TESTDIR"
exit $rc

