"""Generate a simple placeholder VelaPet image as a PNG (stdlib only)."""

import struct
import sys
import zlib

sys.stdout.reconfigure(encoding="utf-8", errors="replace")

W, H = 220, 176
SS = 3  # supersampling factor

OUT = r"C:\Users\keids\home_pet.png"

BODY = (255, 182, 216)
BODY_DARK = (247, 158, 198)
EAR = (255, 160, 200)
EYE = (52, 64, 84)
WHITE = (255, 255, 255)
CHEEK = (255, 138, 178)
MOUTH = (52, 64, 84)


def in_ellipse(x, y, cx, cy, rx, ry):
    dx = (x - cx) / rx
    dy = (y - cy) / ry
    return dx * dx + dy * dy <= 1.0


def sample(x, y):
    """Return (r, g, b, a) for a supersampled coordinate."""
    cx = W * 0.5
    cy = H * 0.56
    rx = W * 0.36
    ry = H * 0.34

    # Ears behind the body.
    for sx in (-1, 1):
        if in_ellipse(x, y, cx + sx * rx * 0.58, cy - ry * 0.92,
                      rx * 0.28, ry * 0.26):
            return EAR + (255,)

    if not in_ellipse(x, y, cx, cy, rx, ry):
        return (0, 0, 0, 0)

    # Eyes with a highlight.
    for sx in (-1, 1):
        ex = cx + sx * rx * 0.34
        ey = cy - ry * 0.16
        if in_ellipse(x, y, ex - rx * 0.03, ey - ry * 0.04,
                      rx * 0.035, ry * 0.05):
            return WHITE + (255,)
        if in_ellipse(x, y, ex, ey, rx * 0.10, ry * 0.14):
            return EYE + (255,)

    # Mouth.
    if in_ellipse(x, y, cx, cy + ry * 0.34, rx * 0.11, ry * 0.07):
        return MOUTH + (255,)

    # Cheeks.
    for sx in (-1, 1):
        if in_ellipse(x, y, cx + sx * rx * 0.62, cy + ry * 0.20,
                      rx * 0.15, ry * 0.10):
            return CHEEK + (255,)

    # Subtle shading on the lower half of the body.
    if y > cy + ry * 0.15:
        return BODY_DARK + (255,)

    return BODY + (255,)


def build_rows():
    rows = []
    inv = 1.0 / (SS * SS)
    for py in range(H):
        row = bytearray([0])  # filter type 0
        for px in range(W):
            r = g = b = a = 0.0
            for sy in range(SS):
                y = py + (sy + 0.5) / SS
                for sx in range(SS):
                    x = px + (sx + 0.5) / SS
                    sr, sg, sb, sa = sample(x, y)
                    if sa:
                        r += sr
                        g += sg
                        b += sb
                        a += sa
            if a > 0:
                n = a / 255.0
                row += bytes((int(r / n + 0.5), int(g / n + 0.5),
                              int(b / n + 0.5), int(a * inv + 0.5)))
            else:
                row += b"\x00\x00\x00\x00"
        rows.append(bytes(row))
    return b"".join(rows)


def chunk(tag, data):
    return (struct.pack(">I", len(data)) + tag + data
            + struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF))


def main():
    raw = build_rows()
    png = (b"\x89PNG\r\n\x1a\n"
           + chunk(b"IHDR", struct.pack(">IIBBBBB", W, H, 8, 6, 0, 0, 0))
           + chunk(b"IDAT", zlib.compress(raw, 9))
           + chunk(b"IEND", b""))
    with open(OUT, "wb") as fp:
        fp.write(png)
    print(f"wrote {OUT}: {len(png)} bytes, {W}x{H} RGBA")


if __name__ == "__main__":
    main()

