#include <nuttx/config.h>

#include <fcntl.h>
#include <pthread.h>
#include <stdint.h>
#include <unistd.h>

#include <lvgl/lvgl.h>

#include "vela_pet_api.h"
#include "velapet_ui.h"

/* Simulated activity.  Auto steps advance the 3000-step daily task in about a
 * minute; one KEY2 press is worth a burst of walking.  Only KEY2 (bit 0) is
 * wired on this board - see sf32lb52_buttons.c.
 */
#define DEMO_POLL_MS            200
#define DEMO_STEPS_PER_TICK     100
#define DEMO_TICKS_PER_STEP     10          /* x200ms => one tick every 2s */
#define DEMO_STEPS_PER_PRESS    500
#define DEMO_MINUTES_PER_PRESS  2
#define DEMO_BUTTON_KEY2        (1u << 0)

static volatile int g_dirty;
static volatile int g_running;
static pthread_t g_thread;

static int read_buttons(int fd)
{
  btn_buttonset_t set = 0;

  if (fd >= 0 && read(fd, &set, sizeof(set)) == (ssize_t)sizeof(set))
    {
      return (int)set;
    }

  return -1;
}

static void *demo_worker(void *arg)
{
  int fd;
  int previous = 0;
  int ticks = 0;

  (void)arg;

  fd = open("/dev/buttons", O_RDONLY);

  while (g_running)
    {
      usleep(DEMO_POLL_MS * 1000);

      /* KEY2 press edge. */
      int current = read_buttons(fd);
      if (current >= 0)
        {
          if ((current & DEMO_BUTTON_KEY2) && !(previous & DEMO_BUTTON_KEY2))
            {
              vela_pet_update_steps(DEMO_STEPS_PER_PRESS);
              vela_pet_update_exercise_time(DEMO_MINUTES_PER_PRESS);
              g_dirty = 1;
            }

          previous = current;
        }

      /* Ambient steps.  Note: vela_pet_update_steps() saves on every call;
       * that is cheap on the current tmpfs /data but will need batching once
       * /data lives on NOR flash.
       */
      if (++ticks >= DEMO_TICKS_PER_STEP)
        {
          ticks = 0;
          vela_pet_update_steps(DEMO_STEPS_PER_TICK);
          g_dirty = 1;
        }
    }

  if (fd >= 0)
    {
      close(fd);
    }

  return NULL;
}

static void demo_refresh_timer(lv_timer_t *timer)
{
  (void)timer;

  if (g_dirty)
    {
      g_dirty = 0;
      velapet_ui_refresh_all();
    }
}

int velapet_demo_input_start(void)
{
  if (g_running)
    {
      return 0;
    }

  g_running = 1;

  if (pthread_create(&g_thread, NULL, demo_worker, NULL) != 0)
    {
      g_running = 0;
      return -1;
    }

  pthread_detach(g_thread);

  /* Runs in the LVGL thread; the worker only sets the dirty flag. */
  lv_timer_create(demo_refresh_timer, DEMO_POLL_MS, NULL);
  return 0;
}
