$t = "C:\Users\keids\tools\sftool\sftool.exe"
$bin = "D:\桌面\velapet_nuttx.bin@0x12010000"

function Port-Present { [System.IO.Ports.SerialPort]::GetPortNames() -contains "COM5" }

$deadline = (Get-Date).AddSeconds(240)

Write-Output "waiting for COM5 to disappear (unplug the board)..."
while ((Get-Date) -lt $deadline -and (Port-Present)) { Start-Sleep -Milliseconds 200 }
if (-not (Get-Date) -lt $deadline) { Write-Output "timeout waiting for unplug"; exit 1 }

Write-Output "unplugged. Waiting for replug, will fire immediately..."
while ((Get-Date) -lt $deadline -and -not (Port-Present)) { Start-Sleep -Milliseconds 50 }
Write-Output "COM5 back at $(Get-Date -Format HH:mm:ss) - flashing now"

$ok = $false
for ($i = 1; $i -le 12; $i++) {
    & $t -c SF32LB52 -m nor -p COM5 -b 1000000 `
        --before default_reset --after soft_reset `
        --connect-attempts 2 write_flash $bin 2>&1 | Out-Null
    if ($LASTEXITCODE -eq 0) {
        Write-Output "FLASH OK on attempt $i"
        $ok = $true
        break
    }
    Start-Sleep -Milliseconds 300
}
if (-not $ok) { Write-Output "FAILED after 12 attempts" }

