/****************************************************************************
 * Name: sf32lb52_build_time
 *
 * Description:
 *   Return the time this firmware was compiled, parsed from __DATE__ and
 *   __TIME__.
 *
 ****************************************************************************/

static time_t sf32lb52_build_time(void)
{
  static const char months[] = "JanFebMarAprMayJunJulAugSepOctNovDec";
  char month[4];
  const char *found;
  struct tm tm;

  month[0] = __DATE__[0];
  month[1] = __DATE__[1];
  month[2] = __DATE__[2];
  month[3] = '\0';

  found = strstr(months, month);

  memset(&tm, 0, sizeof(tm));
  tm.tm_mon  = found != NULL ? (int)((found - months) / 3) : 0;
  tm.tm_mday = atoi(&__DATE__[4]);
  tm.tm_year = atoi(&__DATE__[7]) - 1900;
  tm.tm_hour = atoi(&__TIME__[0]);
  tm.tm_min  = atoi(&__TIME__[3]);
  tm.tm_sec  = atoi(&__TIME__[6]);
  tm.tm_isdst = -1;

  return mktime(&tm);
}

/****************************************************************************
 * Name: sf32lb52_seed_clock
 *
 * Description:
 *   The DevKit-LCD has no RTC backup battery, so after a power cycle the RTC
 *   reports whatever its hardware default is (observed: 2036-02-06) rather
 *   than the real time.  Seed the clock from the firmware build time when the
 *   RTC looks implausible, so the date shown and the daily task logic have a
 *   sane, reproducible base.
 *
 *   The tolerance is deliberately wide (a day): a clock that is merely a
 *   little stale is left alone, so this does not fight an RTC that actually
 *   keeps time, and a battery-backed RTC added later would survive it.
 *
 ****************************************************************************/

static void sf32lb52_seed_clock(void)
{
  time_t build = sf32lb52_build_time();
  struct timespec now;
  struct timespec want;

  if (build <= 0 || clock_gettime(CLOCK_REALTIME, &now) < 0)
    {
      return;
    }

  if (now.tv_sec >= build - 86400 && now.tv_sec <= build + 86400)
    {
      return;
    }

  want.tv_sec = build;
  want.tv_nsec = 0;

  if (clock_settime(CLOCK_REALTIME, &want) < 0)
    {
      serr("WARN: seeding the clock from the build time failed: %d\n", errno);
      return;
    }

  syslog(LOG_INFO, "INFO: RTC had no usable time, set to build time %ld\n",
         (long)build);
}
#endif
