int vela_pet_checkin(void)
{
  int days = 0;

  pthread_mutex_lock(&g_state_lock);
  if (g_pet == NULL || g_task == NULL)
    {
      pthread_mutex_unlock(&g_state_lock);
      return -1;
    }

  days = task_checkin(g_task, g_pet);
  if (days > 0)
    {
      add_exp_locked(5);
      vela_pet_save_state(g_pet, g_task);
    }

  pthread_mutex_unlock(&g_state_lock);
  return days;
}

